"use strict";
module.exports = {
  PLP_HTML: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Shop — AFORCE (preview)</title>\n<!-- HIDDEN PRE-CUTOVER: never index this route. -->\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Archivo+Black&family=IBM+Plex+Mono:wght@400;500;600&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n/* =====================================================================\n   AForce headless /shop-preview — brand system (v2.1.0 tokens).\n   Cinematic Black #0D0D0D · Signal Red #C1281B · Bone #F5F0E8 ·\n   Soursop Green #1FA35A · Berry Blue #1E5BFF.\n   Archivo Black = display/headers · IBM Plex Mono = spec labels · Inter = body.\n   ===================================================================== */\n:root{\n  --ink:#0D0D0D; --bone:#F5F0E8; --red:#C1281B; --green:#1FA35A; --blue:#1E5BFF;\n  --ink-90:#131313; --ink-line:rgba(245,240,232,.14); --ink-line-2:rgba(245,240,232,.08);\n  --bone-70:rgba(245,240,232,.7); --bone-50:rgba(245,240,232,.5); --bone-32:rgba(245,240,232,.32);\n  --display:'Archivo Black',sans-serif; --mono:'IBM Plex Mono',monospace; --body:'Inter',sans-serif;\n  --gutter:clamp(20px,5vw,72px); --maxw:1240px;\n}\n*{margin:0;padding:0;box-sizing:border-box;}\nhtml{scroll-behavior:smooth;}\nbody{ background:var(--ink); color:var(--bone); font-family:var(--body); font-size:16px; line-height:1.6; -webkit-font-smoothing:antialiased; overflow-x:hidden; }\na{color:inherit;text-decoration:none;}\nbutton{font-family:inherit;cursor:pointer;background:none;border:none;color:inherit;}\nimg{max-width:100%;display:block;}\n::selection{background:var(--red);color:var(--bone);}\n:focus-visible{outline:2px solid var(--blue);outline-offset:3px;}\n.wrap{max-width:var(--maxw);margin:0 auto;padding:0 var(--gutter);}\n.mono{font-family:var(--mono);}\n\n/* ---------- header ---------- */\n.sp-nav{ position:sticky;top:0;z-index:40; display:flex;align-items:center;justify-content:space-between; padding:16px var(--gutter); background:rgba(13,13,13,.86); backdrop-filter:blur(12px); border-bottom:1px solid var(--ink-line-2); }\n.sp-mark{ font-family:var(--display); font-size:17px; letter-spacing:.02em; display:flex; align-items:center; gap:9px; }\n.sp-nn{ display:inline-flex; align-items:center; gap:3px; }\n.sp-nn .n1{ color:var(--red); } .sp-nn .bar{ display:inline-block; width:9px;height:2.5px;background:var(--red); } .sp-nn .n2{ display:inline-block; transform:scaleX(-1); }\n.sp-preview-tag{ font-family:var(--mono); font-size:10px; letter-spacing:.18em; text-transform:uppercase; color:var(--bone-32); border:1px solid var(--ink-line); border-radius:999px; padding:4px 10px; }\n.cart-btn{ display:inline-flex; align-items:center; gap:8px; font-family:var(--mono); font-size:12px; letter-spacing:.08em; text-transform:uppercase; border:1px solid var(--ink-line); border-radius:999px; padding:9px 15px; min-height:40px; transition:border-color .2s; }\n.cart-btn:hover{ border-color:var(--bone-50); }\n.cart-btn [data-cart-count]{ font-family:var(--display); font-size:12px; min-width:18px; height:18px; border-radius:50%; background:var(--red); color:var(--bone); display:inline-flex; align-items:center; justify-content:center; }\n.cart-btn [data-cart-count][data-empty=\"true\"]{ background:transparent; color:var(--bone-50); }\n\n/* ---------- page heads ---------- */\n.sp-head{ padding:clamp(48px,8vh,110px) 0 clamp(28px,4vw,44px); }\n.sp-eyebrow{ font-family:var(--mono); font-size:11px; letter-spacing:.24em; text-transform:uppercase; color:var(--red); }\n.sp-h1{ font-family:var(--display); font-weight:400; letter-spacing:-.02em; line-height:1; font-size:clamp(38px,7vw,84px); margin-top:14px; }\n.sp-sub{ margin-top:18px; color:var(--bone-70); max-width:46ch; font-size:clamp(15px,1.5vw,18px); }\n\n/* ---------- product grid (PLP) ---------- */\n.sp-section-label{ font-family:var(--mono); font-size:11px; letter-spacing:.2em; text-transform:uppercase; color:var(--bone-50); padding:0 var(--gutter); max-width:var(--maxw); margin:clamp(30px,5vw,56px) auto 0; }\n.grid{ max-width:var(--maxw); margin:18px auto 0; padding:0 var(--gutter) clamp(48px,8vw,96px); display:grid; grid-template-columns:repeat(auto-fill,minmax(260px,1fr)); gap:clamp(16px,2vw,28px); }\n.card{ display:flex; flex-direction:column; border:1px solid var(--ink-line-2); border-radius:6px; overflow:hidden; background:var(--ink-90); transition:border-color .25s, transform .25s; }\n.card:hover{ border-color:var(--ink-line); transform:translateY(-2px); }\n.card-media{ aspect-ratio:1/1; background:#0a0a0a; display:flex; align-items:center; justify-content:center; overflow:hidden; }\n.card-media img{ width:100%; height:100%; object-fit:contain; padding:14%; transition:transform .4s ease; }\n.card:hover .card-media img{ transform:scale(1.05); }\n.card-body{ padding:18px 18px 20px; display:flex; flex-direction:column; gap:8px; flex:1; }\n.card-type{ font-family:var(--mono); font-size:9.5px; letter-spacing:.18em; text-transform:uppercase; color:var(--bone-32); }\n.card-title{ font-family:var(--display); font-weight:400; font-size:clamp(17px,1.6vw,21px); line-height:1.1; }\n.card-price{ font-family:var(--mono); font-size:14px; color:var(--bone-70); margin-top:auto; }\n.card-cta{ margin-top:12px; display:flex; gap:8px; }\n.card-cta .btn{ flex:1; text-align:center; }\n\n/* buttons */\n.btn{ font-family:var(--body); font-weight:600; font-size:13px; letter-spacing:.04em; border-radius:4px; padding:12px 16px; min-height:44px; display:inline-flex; align-items:center; justify-content:center; gap:8px; transition:background .2s, color .2s, border-color .2s; }\n.btn-primary{ background:var(--red); color:var(--bone); } .btn-primary:hover{ background:#a71f14; }\n.btn-ghost{ border:1px solid var(--ink-line); color:var(--bone); } .btn-ghost:hover{ border-color:var(--bone-50); }\n.btn:disabled{ opacity:.4; pointer-events:none; }\n\n/* skeleton / states */\n.sp-state{ max-width:var(--maxw); margin:0 auto; padding:clamp(40px,8vw,90px) var(--gutter); text-align:center; color:var(--bone-50); }\n.sp-state .mono{ font-size:12px; letter-spacing:.14em; text-transform:uppercase; }\n.skel{ background:linear-gradient(90deg, #111 0%, #191919 50%, #111 100%); background-size:200% 100%; animation:sk 1.3s ease infinite; }\n@keyframes sk{ 0%{background-position:200% 0;} 100%{background-position:-200% 0;} }\n.card.skel-card .card-media{ background:#111; } .card.skel-card .card-title,.card.skel-card .card-price{ height:14px; border-radius:3px; }\n\n/* ---------- PDP ---------- */\n.pdp{ max-width:var(--maxw); margin:0 auto; padding:clamp(30px,5vw,64px) var(--gutter) clamp(48px,8vw,96px); display:grid; grid-template-columns:1.1fr 1fr; gap:clamp(30px,5vw,72px); align-items:start; }\n@media (max-width:820px){ .pdp{ grid-template-columns:1fr; } }\n.pdp-media{ position:sticky; top:90px; aspect-ratio:1/1; background:var(--ink-90); border:1px solid var(--ink-line-2); border-radius:8px; display:flex; align-items:center; justify-content:center; overflow:hidden; }\n.pdp-media img{ width:100%; height:100%; object-fit:contain; padding:12%; }\n.pdp-type{ font-family:var(--mono); font-size:11px; letter-spacing:.2em; text-transform:uppercase; color:var(--red); }\n.pdp-title{ font-family:var(--display); font-weight:400; letter-spacing:-.02em; line-height:1; font-size:clamp(30px,4.4vw,52px); margin:12px 0; }\n.pdp-price{ font-family:var(--mono); font-size:20px; color:var(--bone); }\n.pdp-desc{ margin-top:22px; color:var(--bone-70); line-height:1.8; max-width:52ch; }\n.pdp-variants{ margin-top:26px; display:flex; flex-wrap:wrap; gap:10px; }\n.variant{ font-family:var(--mono); font-size:12px; letter-spacing:.06em; border:1.5px solid var(--ink-line); border-radius:999px; padding:11px 16px; min-height:44px; transition:border-color .2s, background .2s; }\n.variant.on{ border-color:var(--bone); background:rgba(245,240,232,.06); }\n.variant.oos{ opacity:.35; text-decoration:line-through; pointer-events:none; }\n.pdp-add{ margin-top:26px; width:100%; }\n.pdp-note{ margin-top:12px; font-family:var(--mono); font-size:10.5px; letter-spacing:.06em; color:var(--bone-32); }\n.pdp-back{ display:inline-flex; align-items:center; gap:8px; font-family:var(--mono); font-size:11px; letter-spacing:.14em; text-transform:uppercase; color:var(--bone-50); margin-bottom:22px; }\n.pdp-back:hover{ color:var(--bone); }\n\n/* ---------- cart drawer ---------- */\n.cd-veil{ position:fixed; inset:0; z-index:80; background:rgba(0,0,0,.55); opacity:0; pointer-events:none; transition:opacity .3s; }\n.cd-veil.open{ opacity:1; pointer-events:auto; }\n.cd-drawer{ position:fixed; top:0; right:0; bottom:0; z-index:81; width:min(430px,92vw); background:var(--ink); border-left:1px solid var(--ink-line); display:flex; flex-direction:column; transform:translateX(100%); transition:transform .35s cubic-bezier(.2,.7,.2,1); }\n.cd-drawer.open{ transform:none; }\n.cd-drawer[data-loading=\"true\"]{ cursor:progress; }\n.cd-head{ display:flex; align-items:center; justify-content:space-between; padding:20px 22px; border-bottom:1px solid var(--ink-line-2); font-family:var(--display); font-size:18px; letter-spacing:.01em; }\n.cd-close{ font-size:26px; line-height:1; color:var(--bone-50); width:40px;height:40px; } .cd-close:hover{ color:var(--bone); }\n.cd-lines{ flex:1; overflow-y:auto; padding:8px 22px; }\n.cd-empty{ color:var(--bone-32); font-family:var(--mono); font-size:12px; letter-spacing:.1em; text-transform:uppercase; padding:40px 0; text-align:center; }\n.cd-line{ display:grid; grid-template-columns:60px 1fr auto; gap:14px; padding:18px 0; border-bottom:1px solid var(--ink-line-2); }\n.cd-thumb{ width:60px; height:60px; background:var(--ink-90); border-radius:4px; overflow:hidden; display:flex; align-items:center; justify-content:center; }\n.cd-thumb img{ width:100%; height:100%; object-fit:contain; padding:8%; }\n.cd-title{ font-family:var(--display); font-size:14px; line-height:1.2; }\n.cd-meta{ font-family:var(--mono); font-size:10.5px; letter-spacing:.06em; color:var(--bone-50); margin-top:4px; }\n.cd-plan{ font-family:var(--mono); font-size:9.5px; letter-spacing:.12em; text-transform:uppercase; color:var(--green); margin-top:5px; }\n.cd-qty{ display:flex; align-items:center; gap:8px; margin-top:10px; }\n.cd-qty button{ width:30px;height:30px; border:1px solid var(--ink-line); border-radius:4px; color:var(--bone); font-size:16px; }\n.cd-qty button:hover{ border-color:var(--bone-50); }\n.cd-qty span{ font-family:var(--mono); font-size:13px; min-width:20px; text-align:center; }\n.cd-rm{ margin-left:6px; font-family:var(--mono); font-size:10px; letter-spacing:.1em; text-transform:uppercase; color:var(--bone-32); } .cd-rm:hover{ color:var(--red); }\n.cd-price{ font-family:var(--mono); font-size:13px; }\n.cd-foot{ border-top:1px solid var(--ink-line); padding:20px 22px calc(20px + env(safe-area-inset-bottom)); }\n.cd-sub{ display:flex; justify-content:space-between; align-items:baseline; font-family:var(--display); font-size:18px; }\n.cd-ship{ font-family:var(--mono); font-size:10.5px; letter-spacing:.06em; color:var(--bone-32); margin:8px 0 16px; }\n.cd-checkout{ display:block; text-align:center; background:var(--red); color:var(--bone); font-family:var(--display); font-size:15px; letter-spacing:.02em; border-radius:5px; padding:18px; transition:background .2s; }\n.cd-checkout:hover{ background:#a71f14; }\n.cd-checkout[aria-disabled=\"true\"]{ opacity:.4; pointer-events:none; }\n.cd-toast{ position:fixed; bottom:24px; left:50%; transform:translate(-50%,20px); z-index:90; background:var(--bone); color:var(--ink); font-family:var(--mono); font-size:12px; letter-spacing:.06em; padding:12px 20px; border-radius:6px; opacity:0; pointer-events:none; transition:opacity .25s, transform .25s; }\n.cd-toast.show{ opacity:1; transform:translate(-50%,0); }\n\n/* footer */\n.sp-foot{ padding:clamp(28px,4vw,44px) var(--gutter); border-top:1px solid var(--ink-line-2); font-family:var(--mono); font-size:10.5px; letter-spacing:.08em; color:var(--bone-32); display:flex; flex-wrap:wrap; gap:12px 26px; }\n\n@media (max-width:640px){ .sp-nav .sp-preview-tag{ display:none; } }\n@media (prefers-reduced-motion:reduce){ *{ animation:none !important; } .card:hover{ transform:none; } }\n\n</style>\n</head>\n<body>\n\n<nav class=\"sp-nav\">\n  <a class=\"sp-mark\" href=\"/\" aria-label=\"AFORCE home\">\n    <span class=\"sp-nn\"><span class=\"n1\">N</span><span class=\"bar\"></span><span class=\"n2\">N</span></span> AFORCE\n    <span class=\"sp-preview-tag\">Shop Preview</span>\n  </a>\n  <button class=\"cart-btn\" type=\"button\" data-cart-open>Cart <span data-cart-count data-empty=\"true\">0</span></button>\n</nav>\n\n<header class=\"sp-head wrap\">\n  <p class=\"sp-eyebrow\">The Standard</p>\n  <h1 class=\"sp-h1\">Shop the ritual.</h1>\n  <p class=\"sp-sub\">Every formulation, on drinkaforce.com. Checkout is the only handoff.</p>\n</header>\n\n<!-- combos (driven by a Shopify collection; hidden if the collection is empty/absent) -->\n<div id=\"combosLabel\" class=\"sp-section-label\" hidden>Launch Combos</div>\n<div id=\"combos\" class=\"grid\" hidden></div>\n\n<div class=\"sp-section-label\">All Products</div>\n<div id=\"grid\" class=\"grid\" aria-live=\"polite\">\n  <!-- skeletons -->\n  <div class=\"card skel-card\"><div class=\"card-media skel\"></div><div class=\"card-body\"><span class=\"card-title skel\"></span><span class=\"card-price skel\"></span></div></div>\n  <div class=\"card skel-card\"><div class=\"card-media skel\"></div><div class=\"card-body\"><span class=\"card-title skel\"></span><span class=\"card-price skel\"></span></div></div>\n  <div class=\"card skel-card\"><div class=\"card-media skel\"></div><div class=\"card-body\"><span class=\"card-title skel\"></span><span class=\"card-price skel\"></span></div></div>\n</div>\n<div id=\"state\" class=\"sp-state\" hidden></div>\n\n<footer class=\"sp-foot\">\n  <span>AFORCE Hydration, Inc.</span>\n  <span>Performance Is Non-Negotiable.</span>\n  <span>Preview build — not indexed.</span>\n</footer>\n\n<script>\n/* =====================================================================\n   AForce Headless — CartProvider (vanilla, brand-native slide-out drawer).\n   Mounts ONLY on /shop-preview pages (not global) until cutover.\n   - cart id persisted in first-party cookie `aforce_cart_id` (30-day).\n   - all Shopify calls go through /api/cart/* so the token stays server-side.\n   - optimistic quantity/remove with rollback + toast on error.\n   - checkout CTA → cart.checkoutUrl (Shopify checkout on shop.drinkaforce.com).\n   Exposes window.AForceCart: { addLine, updateLine, removeLine, open, close, refresh, get }.\n   ===================================================================== */\n(function () {\n  \"use strict\";\n\n  var COOKIE = \"aforce_cart_id\";\n  var COOKIE_DAYS = 30;\n  var cart = null;         // last known server cart\n  var loading = false;\n  var els = {};\n\n  /* ---------- cookie ---------- */\n  function setCookie(v) {\n    var d = new Date(); d.setTime(d.getTime() + COOKIE_DAYS * 864e5);\n    document.cookie = COOKIE + \"=\" + encodeURIComponent(v) + \";expires=\" + d.toUTCString() + \";path=/;SameSite=Lax\";\n  }\n  function getCookie() {\n    var m = document.cookie.match(new RegExp(\"(?:^|; )\" + COOKIE + \"=([^;]*)\"));\n    return m ? decodeURIComponent(m[1]) : null;\n  }\n  function clearCookie() { document.cookie = COOKIE + \"=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/\"; }\n\n  /* ---------- api ---------- */\n  function api(path, opts) {\n    return fetch(path, Object.assign({ headers: { \"Content-Type\": \"application/json\" } }, opts))\n      .then(function (r) { return r.json().then(function (j) { if (!r.ok) throw new Error(j.error || (\"HTTP \" + r.status)); return j; }); });\n  }\n\n  /* ---------- money ---------- */\n  function money(m) {\n    if (!m) return \"\";\n    var n = parseFloat(m.amount || 0);\n    try { return new Intl.NumberFormat(\"en-US\", { style: \"currency\", currency: m.currencyCode || \"USD\" }).format(n); }\n    catch (e) { return \"$\" + n.toFixed(2); }\n  }\n\n  /* ---------- render ---------- */\n  function count() { return cart && cart.totalQuantity ? cart.totalQuantity : 0; }\n  function renderBadges() {\n    document.querySelectorAll(\"[data-cart-count]\").forEach(function (b) {\n      var c = count(); b.textContent = c; b.setAttribute(\"data-empty\", c ? \"false\" : \"true\");\n    });\n  }\n  function esc(s) { return (s == null ? \"\" : String(s)).replace(/[&<>\"]/g, function (c) { return ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" })[c]; }); }\n\n  function renderDrawer() {\n    renderBadges();\n    var body = els.body, foot = els.foot;\n    if (!cart || !cart.lines || !cart.lines.nodes.length) {\n      body.innerHTML = '<p class=\"cd-empty\">Your cart is empty.</p>';\n      foot.style.display = \"none\";\n      return;\n    }\n    foot.style.display = \"\";\n    body.innerHTML = cart.lines.nodes.map(function (ln) {\n      var v = ln.merchandise || {};\n      var plan = ln.sellingPlanAllocation && ln.sellingPlanAllocation.sellingPlan;\n      var img = v.image ? '<img src=\"' + esc(v.image.url) + '\" alt=\"' + esc(v.image.altText || \"\") + '\">' : '<span class=\"cd-noimg\"></span>';\n      var opts = (v.selectedOptions || []).filter(function (o) { return o.value && o.value !== \"Default Title\"; })\n        .map(function (o) { return esc(o.value); }).join(\" · \");\n      return '<div class=\"cd-line\" data-line=\"' + esc(ln.id) + '\">' +\n        '<div class=\"cd-thumb\">' + img + '</div>' +\n        '<div class=\"cd-info\">' +\n        '<div class=\"cd-title\">' + esc(v.product ? v.product.title : v.title) + '</div>' +\n        (opts ? '<div class=\"cd-meta\">' + opts + '</div>' : \"\") +\n        (plan ? '<div class=\"cd-plan\">' + esc(plan.name) + '</div>' : '<div class=\"cd-plan\">One-time</div>') +\n        '<div class=\"cd-qty\">' +\n        '<button type=\"button\" data-qd aria-label=\"Decrease\">–</button>' +\n        '<span>' + ln.quantity + '</span>' +\n        '<button type=\"button\" data-qi aria-label=\"Increase\">+</button>' +\n        '<button type=\"button\" class=\"cd-rm\" data-rm>Remove</button>' +\n        '</div>' +\n        '</div>' +\n        '<div class=\"cd-price\">' + money(ln.cost && ln.cost.totalAmount) + '</div>' +\n        '</div>';\n    }).join(\"\");\n    els.subtotal.textContent = money(cart.cost && cart.cost.subtotalAmount);\n    els.checkout.href = cart.checkoutUrl || \"#\";\n    els.checkout.setAttribute(\"aria-disabled\", cart.checkoutUrl ? \"false\" : \"true\");\n  }\n\n  /* ---------- toast ---------- */\n  function toast(msg) {\n    els.toast.textContent = msg; els.toast.classList.add(\"show\");\n    clearTimeout(toast._t); toast._t = setTimeout(function () { els.toast.classList.remove(\"show\"); }, 3200);\n  }\n\n  /* ---------- mutations (optimistic where safe) ---------- */\n  function setLoading(v) { loading = v; els.drawer.setAttribute(\"data-loading\", v ? \"true\" : \"false\"); }\n\n  function addLine(merchandiseId, quantity, opts) {\n    quantity = quantity || 1; opts = opts || {};\n    var line = { merchandiseId: merchandiseId, quantity: quantity };\n    if (opts.sellingPlanId) line.sellingPlanId = opts.sellingPlanId;\n    setLoading(true);\n    var id = getCookie();\n    var p = id\n      ? api(\"/api/cart/add\", { method: \"POST\", body: JSON.stringify({ cartId: id, lines: [line] }) })\n      : api(\"/api/cart/create\", { method: \"POST\", body: JSON.stringify({ lines: [line] }) });\n    return p.then(function (j) {\n      if (!id && j.cart) setCookie(j.cart.id);\n      cart = j.cart; renderDrawer(); open(); toast(\"Added to cart\");\n    }).catch(function (e) {\n      // A stale/expired cart id can make add fail — recreate once.\n      if (id) { clearCookie(); return api(\"/api/cart/create\", { method: \"POST\", body: JSON.stringify({ lines: [line] }) })\n        .then(function (j) { if (j.cart) setCookie(j.cart.id); cart = j.cart; renderDrawer(); open(); toast(\"Added to cart\"); })\n        .catch(function (e2) { toast(\"Couldn't add — try again\"); }); }\n      toast(\"Couldn't add — try again\");\n    }).finally(function () { setLoading(false); });\n  }\n\n  function updateLine(lineId, quantity) {\n    var id = getCookie(); if (!id) return Promise.resolve();\n    if (quantity <= 0) return removeLine(lineId);\n    // optimistic\n    var prev = JSON.parse(JSON.stringify(cart));\n    var ln = cart.lines.nodes.filter(function (l) { return l.id === lineId; })[0];\n    if (ln) { ln.quantity = quantity; renderDrawer(); }\n    setLoading(true);\n    return api(\"/api/cart/update\", { method: \"POST\", body: JSON.stringify({ cartId: id, lines: [{ id: lineId, quantity: quantity }] }) })\n      .then(function (j) { cart = j.cart; renderDrawer(); })\n      .catch(function () { cart = prev; renderDrawer(); toast(\"Couldn't update — reverted\"); })\n      .finally(function () { setLoading(false); });\n  }\n\n  function removeLine(lineId) {\n    var id = getCookie(); if (!id) return Promise.resolve();\n    var prev = JSON.parse(JSON.stringify(cart));\n    cart.lines.nodes = cart.lines.nodes.filter(function (l) { return l.id !== lineId; }); renderDrawer();\n    setLoading(true);\n    return api(\"/api/cart/remove\", { method: \"POST\", body: JSON.stringify({ cartId: id, lineIds: [lineId] }) })\n      .then(function (j) { cart = j.cart; renderDrawer(); })\n      .catch(function () { cart = prev; renderDrawer(); toast(\"Couldn't remove — reverted\"); })\n      .finally(function () { setLoading(false); });\n  }\n\n  function refresh() {\n    var id = getCookie(); if (!id) { renderDrawer(); return Promise.resolve(); }\n    return api(\"/api/cart/get?id=\" + encodeURIComponent(id)).then(function (j) {\n      if (!j.cart) { clearCookie(); cart = null; } else { cart = j.cart; }\n      renderDrawer();\n    }).catch(function () { /* keep last state */ });\n  }\n\n  /* ---------- drawer open/close ---------- */\n  function open() { els.drawer.classList.add(\"open\"); els.veil.classList.add(\"open\"); document.body.style.overflow = \"hidden\"; }\n  function close() { els.drawer.classList.remove(\"open\"); els.veil.classList.remove(\"open\"); document.body.style.overflow = \"\"; }\n\n  /* ---------- mount ---------- */\n  function mount() {\n    var wrap = document.createElement(\"div\");\n    wrap.innerHTML =\n      '<div class=\"cd-veil\" data-cart-veil></div>' +\n      '<aside class=\"cd-drawer\" data-cart-drawer aria-label=\"Cart\" data-loading=\"false\">' +\n      '<header class=\"cd-head\"><span>Your Ritual</span><button type=\"button\" class=\"cd-close\" data-cart-close aria-label=\"Close cart\">×</button></header>' +\n      '<div class=\"cd-lines\" data-cart-body></div>' +\n      '<footer class=\"cd-foot\" data-cart-foot>' +\n      '<div class=\"cd-sub\"><span>Subtotal</span><span data-cart-subtotal></span></div>' +\n      '<p class=\"cd-ship\">Shipping &amp; taxes calculated at checkout.</p>' +\n      '<a class=\"cd-checkout\" data-cart-checkout href=\"#\">Checkout →</a>' +\n      '</footer></aside>' +\n      '<div class=\"cd-toast\" data-cart-toast role=\"status\"></div>';\n    document.body.appendChild(wrap);\n    els.veil = wrap.querySelector(\"[data-cart-veil]\");\n    els.drawer = wrap.querySelector(\"[data-cart-drawer]\");\n    els.body = wrap.querySelector(\"[data-cart-body]\");\n    els.foot = wrap.querySelector(\"[data-cart-foot]\");\n    els.subtotal = wrap.querySelector(\"[data-cart-subtotal]\");\n    els.checkout = wrap.querySelector(\"[data-cart-checkout]\");\n    els.toast = wrap.querySelector(\"[data-cart-toast]\");\n\n    els.veil.addEventListener(\"click\", close);\n    wrap.querySelector(\"[data-cart-close]\").addEventListener(\"click\", close);\n    document.addEventListener(\"keydown\", function (e) { if (e.key === \"Escape\") close(); });\n\n    document.addEventListener(\"click\", function (e) {\n      if (e.target.closest(\"[data-cart-open]\")) { e.preventDefault(); open(); }\n      var line = e.target.closest(\".cd-line\"); if (!line) return;\n      var id = line.getAttribute(\"data-line\");\n      var ln = cart && cart.lines.nodes.filter(function (l) { return l.id === id; })[0];\n      if (!ln) return;\n      if (e.target.closest(\"[data-qi]\")) updateLine(id, ln.quantity + 1);\n      else if (e.target.closest(\"[data-qd]\")) updateLine(id, ln.quantity - 1);\n      else if (e.target.closest(\"[data-rm]\")) removeLine(id);\n    });\n\n    renderDrawer();\n    refresh();\n  }\n\n  window.AForceCart = { addLine: addLine, updateLine: updateLine, removeLine: removeLine, open: open, close: close, refresh: refresh, get: function () { return cart; } };\n  if (document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\", mount); else mount();\n})();\n\n</script>\n<script>\n(function(){\n  \"use strict\";\n  function money(m){ if(!m) return \"\"; var n=parseFloat(m.amount||0); try{return new Intl.NumberFormat(\"en-US\",{style:\"currency\",currency:m.currencyCode||\"USD\"}).format(n);}catch(e){return \"$\"+n.toFixed(2);} }\n  function esc(s){ return (s==null?\"\":String(s)).replace(/[&<>\"]/g,function(c){return({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"})[c];}); }\n  function priceLabel(p){\n    var mn=p.priceRange&&p.priceRange.minVariantPrice, mx=p.priceRange&&p.priceRange.maxVariantPrice;\n    if(mn&&mx&&mn.amount!==mx.amount) return \"From \"+money(mn);\n    return money(mn);\n  }\n  function firstAvailableVariant(p){\n    var vs=(p.variants&&p.variants.nodes)||[];\n    return vs.filter(function(v){return v.availableForSale;})[0]||vs[0]||null;\n  }\n  function card(p){\n    var img=p.featuredImage?('<img src=\"'+esc(p.featuredImage.url)+'\" alt=\"'+esc(p.featuredImage.altText||p.title)+'\" loading=\"lazy\">'):'<span></span>';\n    var v=firstAvailableVariant(p);\n    var soldOut=v&&!v.availableForSale;\n    return '<article class=\"card\">'+\n      '<a class=\"card-media\" href=\"/shop-preview/'+esc(p.handle)+'\">'+img+'</a>'+\n      '<div class=\"card-body\">'+\n        (p.productType?'<span class=\"card-type\">'+esc(p.productType)+'</span>':'')+\n        '<a class=\"card-title\" href=\"/shop-preview/'+esc(p.handle)+'\">'+esc(p.title)+'</a>'+\n        '<span class=\"card-price\">'+priceLabel(p)+'</span>'+\n        '<div class=\"card-cta\">'+\n          '<a class=\"btn btn-ghost\" href=\"/shop-preview/'+esc(p.handle)+'\">View</a>'+\n          (v&&!soldOut?'<button class=\"btn btn-primary\" type=\"button\" data-add=\"'+esc(v.id)+'\">Add</button>':'<button class=\"btn btn-ghost\" type=\"button\" disabled>Sold out</button>')+\n        '</div>'+\n      '</div></article>';\n  }\n  function showState(html){ var s=document.getElementById(\"state\"); s.innerHTML=html; s.hidden=false; }\n\n  function load(){\n    fetch(\"/api/shop/products\").then(function(r){ return r.json().then(function(j){ if(!r.ok) throw Object.assign(new Error(j.error||(\"HTTP \"+r.status)),{status:r.status}); return j; }); })\n      .then(function(j){\n        var grid=document.getElementById(\"grid\");\n        var ps=j.products||[];\n        if(!ps.length){ grid.innerHTML=\"\"; showState('<p class=\"mono\">No products found.</p>'); return; }\n        grid.innerHTML=ps.map(card).join(\"\");\n      })\n      .catch(function(e){\n        document.getElementById(\"grid\").innerHTML=\"\";\n        if(e.status===404){ showState('<p class=\"mono\">Shop preview is disabled.</p>'); }\n        else if(e.status===503){ showState('<p class=\"mono\">Connect Shopify to load products.</p><p style=\"margin-top:10px;font-size:13px\">Set SHOPIFY_STORE_DOMAIN + SHOPIFY_STOREFRONT_ACCESS_TOKEN in Vercel.</p>'); }\n        else{ showState('<p class=\"mono\">Couldn’t load products.</p>'); }\n      });\n\n    fetch(\"/api/shop/collection\").then(function(r){ return r.ok?r.json():null; }).then(function(j){\n      if(!j||!j.collection||!j.collection.products||!j.collection.products.length) return;\n      var wrap=document.getElementById(\"combos\");\n      wrap.innerHTML=j.collection.products.map(card).join(\"\");\n      wrap.hidden=false; document.getElementById(\"combosLabel\").hidden=false;\n    }).catch(function(){});\n  }\n\n  document.addEventListener(\"click\", function(e){\n    var add=e.target.closest(\"[data-add]\"); if(!add) return;\n    add.disabled=true; add.textContent=\"Adding…\";\n    window.AForceCart.addLine(add.getAttribute(\"data-add\"),1).finally(function(){ add.disabled=false; add.textContent=\"Add\"; });\n  });\n\n  load();\n})();\n</script>\n</body>\n</html>\n",
  PDP_HTML: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Product — AFORCE (preview)</title>\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Archivo+Black&family=IBM+Plex+Mono:wght@400;500;600&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n/* =====================================================================\n   AForce headless /shop-preview — brand system (v2.1.0 tokens).\n   Cinematic Black #0D0D0D · Signal Red #C1281B · Bone #F5F0E8 ·\n   Soursop Green #1FA35A · Berry Blue #1E5BFF.\n   Archivo Black = display/headers · IBM Plex Mono = spec labels · Inter = body.\n   ===================================================================== */\n:root{\n  --ink:#0D0D0D; --bone:#F5F0E8; --red:#C1281B; --green:#1FA35A; --blue:#1E5BFF;\n  --ink-90:#131313; --ink-line:rgba(245,240,232,.14); --ink-line-2:rgba(245,240,232,.08);\n  --bone-70:rgba(245,240,232,.7); --bone-50:rgba(245,240,232,.5); --bone-32:rgba(245,240,232,.32);\n  --display:'Archivo Black',sans-serif; --mono:'IBM Plex Mono',monospace; --body:'Inter',sans-serif;\n  --gutter:clamp(20px,5vw,72px); --maxw:1240px;\n}\n*{margin:0;padding:0;box-sizing:border-box;}\nhtml{scroll-behavior:smooth;}\nbody{ background:var(--ink); color:var(--bone); font-family:var(--body); font-size:16px; line-height:1.6; -webkit-font-smoothing:antialiased; overflow-x:hidden; }\na{color:inherit;text-decoration:none;}\nbutton{font-family:inherit;cursor:pointer;background:none;border:none;color:inherit;}\nimg{max-width:100%;display:block;}\n::selection{background:var(--red);color:var(--bone);}\n:focus-visible{outline:2px solid var(--blue);outline-offset:3px;}\n.wrap{max-width:var(--maxw);margin:0 auto;padding:0 var(--gutter);}\n.mono{font-family:var(--mono);}\n\n/* ---------- header ---------- */\n.sp-nav{ position:sticky;top:0;z-index:40; display:flex;align-items:center;justify-content:space-between; padding:16px var(--gutter); background:rgba(13,13,13,.86); backdrop-filter:blur(12px); border-bottom:1px solid var(--ink-line-2); }\n.sp-mark{ font-family:var(--display); font-size:17px; letter-spacing:.02em; display:flex; align-items:center; gap:9px; }\n.sp-nn{ display:inline-flex; align-items:center; gap:3px; }\n.sp-nn .n1{ color:var(--red); } .sp-nn .bar{ display:inline-block; width:9px;height:2.5px;background:var(--red); } .sp-nn .n2{ display:inline-block; transform:scaleX(-1); }\n.sp-preview-tag{ font-family:var(--mono); font-size:10px; letter-spacing:.18em; text-transform:uppercase; color:var(--bone-32); border:1px solid var(--ink-line); border-radius:999px; padding:4px 10px; }\n.cart-btn{ display:inline-flex; align-items:center; gap:8px; font-family:var(--mono); font-size:12px; letter-spacing:.08em; text-transform:uppercase; border:1px solid var(--ink-line); border-radius:999px; padding:9px 15px; min-height:40px; transition:border-color .2s; }\n.cart-btn:hover{ border-color:var(--bone-50); }\n.cart-btn [data-cart-count]{ font-family:var(--display); font-size:12px; min-width:18px; height:18px; border-radius:50%; background:var(--red); color:var(--bone); display:inline-flex; align-items:center; justify-content:center; }\n.cart-btn [data-cart-count][data-empty=\"true\"]{ background:transparent; color:var(--bone-50); }\n\n/* ---------- page heads ---------- */\n.sp-head{ padding:clamp(48px,8vh,110px) 0 clamp(28px,4vw,44px); }\n.sp-eyebrow{ font-family:var(--mono); font-size:11px; letter-spacing:.24em; text-transform:uppercase; color:var(--red); }\n.sp-h1{ font-family:var(--display); font-weight:400; letter-spacing:-.02em; line-height:1; font-size:clamp(38px,7vw,84px); margin-top:14px; }\n.sp-sub{ margin-top:18px; color:var(--bone-70); max-width:46ch; font-size:clamp(15px,1.5vw,18px); }\n\n/* ---------- product grid (PLP) ---------- */\n.sp-section-label{ font-family:var(--mono); font-size:11px; letter-spacing:.2em; text-transform:uppercase; color:var(--bone-50); padding:0 var(--gutter); max-width:var(--maxw); margin:clamp(30px,5vw,56px) auto 0; }\n.grid{ max-width:var(--maxw); margin:18px auto 0; padding:0 var(--gutter) clamp(48px,8vw,96px); display:grid; grid-template-columns:repeat(auto-fill,minmax(260px,1fr)); gap:clamp(16px,2vw,28px); }\n.card{ display:flex; flex-direction:column; border:1px solid var(--ink-line-2); border-radius:6px; overflow:hidden; background:var(--ink-90); transition:border-color .25s, transform .25s; }\n.card:hover{ border-color:var(--ink-line); transform:translateY(-2px); }\n.card-media{ aspect-ratio:1/1; background:#0a0a0a; display:flex; align-items:center; justify-content:center; overflow:hidden; }\n.card-media img{ width:100%; height:100%; object-fit:contain; padding:14%; transition:transform .4s ease; }\n.card:hover .card-media img{ transform:scale(1.05); }\n.card-body{ padding:18px 18px 20px; display:flex; flex-direction:column; gap:8px; flex:1; }\n.card-type{ font-family:var(--mono); font-size:9.5px; letter-spacing:.18em; text-transform:uppercase; color:var(--bone-32); }\n.card-title{ font-family:var(--display); font-weight:400; font-size:clamp(17px,1.6vw,21px); line-height:1.1; }\n.card-price{ font-family:var(--mono); font-size:14px; color:var(--bone-70); margin-top:auto; }\n.card-cta{ margin-top:12px; display:flex; gap:8px; }\n.card-cta .btn{ flex:1; text-align:center; }\n\n/* buttons */\n.btn{ font-family:var(--body); font-weight:600; font-size:13px; letter-spacing:.04em; border-radius:4px; padding:12px 16px; min-height:44px; display:inline-flex; align-items:center; justify-content:center; gap:8px; transition:background .2s, color .2s, border-color .2s; }\n.btn-primary{ background:var(--red); color:var(--bone); } .btn-primary:hover{ background:#a71f14; }\n.btn-ghost{ border:1px solid var(--ink-line); color:var(--bone); } .btn-ghost:hover{ border-color:var(--bone-50); }\n.btn:disabled{ opacity:.4; pointer-events:none; }\n\n/* skeleton / states */\n.sp-state{ max-width:var(--maxw); margin:0 auto; padding:clamp(40px,8vw,90px) var(--gutter); text-align:center; color:var(--bone-50); }\n.sp-state .mono{ font-size:12px; letter-spacing:.14em; text-transform:uppercase; }\n.skel{ background:linear-gradient(90deg, #111 0%, #191919 50%, #111 100%); background-size:200% 100%; animation:sk 1.3s ease infinite; }\n@keyframes sk{ 0%{background-position:200% 0;} 100%{background-position:-200% 0;} }\n.card.skel-card .card-media{ background:#111; } .card.skel-card .card-title,.card.skel-card .card-price{ height:14px; border-radius:3px; }\n\n/* ---------- PDP ---------- */\n.pdp{ max-width:var(--maxw); margin:0 auto; padding:clamp(30px,5vw,64px) var(--gutter) clamp(48px,8vw,96px); display:grid; grid-template-columns:1.1fr 1fr; gap:clamp(30px,5vw,72px); align-items:start; }\n@media (max-width:820px){ .pdp{ grid-template-columns:1fr; } }\n.pdp-media{ position:sticky; top:90px; aspect-ratio:1/1; background:var(--ink-90); border:1px solid var(--ink-line-2); border-radius:8px; display:flex; align-items:center; justify-content:center; overflow:hidden; }\n.pdp-media img{ width:100%; height:100%; object-fit:contain; padding:12%; }\n.pdp-type{ font-family:var(--mono); font-size:11px; letter-spacing:.2em; text-transform:uppercase; color:var(--red); }\n.pdp-title{ font-family:var(--display); font-weight:400; letter-spacing:-.02em; line-height:1; font-size:clamp(30px,4.4vw,52px); margin:12px 0; }\n.pdp-price{ font-family:var(--mono); font-size:20px; color:var(--bone); }\n.pdp-desc{ margin-top:22px; color:var(--bone-70); line-height:1.8; max-width:52ch; }\n.pdp-variants{ margin-top:26px; display:flex; flex-wrap:wrap; gap:10px; }\n.variant{ font-family:var(--mono); font-size:12px; letter-spacing:.06em; border:1.5px solid var(--ink-line); border-radius:999px; padding:11px 16px; min-height:44px; transition:border-color .2s, background .2s; }\n.variant.on{ border-color:var(--bone); background:rgba(245,240,232,.06); }\n.variant.oos{ opacity:.35; text-decoration:line-through; pointer-events:none; }\n.pdp-add{ margin-top:26px; width:100%; }\n.pdp-note{ margin-top:12px; font-family:var(--mono); font-size:10.5px; letter-spacing:.06em; color:var(--bone-32); }\n.pdp-back{ display:inline-flex; align-items:center; gap:8px; font-family:var(--mono); font-size:11px; letter-spacing:.14em; text-transform:uppercase; color:var(--bone-50); margin-bottom:22px; }\n.pdp-back:hover{ color:var(--bone); }\n\n/* ---------- cart drawer ---------- */\n.cd-veil{ position:fixed; inset:0; z-index:80; background:rgba(0,0,0,.55); opacity:0; pointer-events:none; transition:opacity .3s; }\n.cd-veil.open{ opacity:1; pointer-events:auto; }\n.cd-drawer{ position:fixed; top:0; right:0; bottom:0; z-index:81; width:min(430px,92vw); background:var(--ink); border-left:1px solid var(--ink-line); display:flex; flex-direction:column; transform:translateX(100%); transition:transform .35s cubic-bezier(.2,.7,.2,1); }\n.cd-drawer.open{ transform:none; }\n.cd-drawer[data-loading=\"true\"]{ cursor:progress; }\n.cd-head{ display:flex; align-items:center; justify-content:space-between; padding:20px 22px; border-bottom:1px solid var(--ink-line-2); font-family:var(--display); font-size:18px; letter-spacing:.01em; }\n.cd-close{ font-size:26px; line-height:1; color:var(--bone-50); width:40px;height:40px; } .cd-close:hover{ color:var(--bone); }\n.cd-lines{ flex:1; overflow-y:auto; padding:8px 22px; }\n.cd-empty{ color:var(--bone-32); font-family:var(--mono); font-size:12px; letter-spacing:.1em; text-transform:uppercase; padding:40px 0; text-align:center; }\n.cd-line{ display:grid; grid-template-columns:60px 1fr auto; gap:14px; padding:18px 0; border-bottom:1px solid var(--ink-line-2); }\n.cd-thumb{ width:60px; height:60px; background:var(--ink-90); border-radius:4px; overflow:hidden; display:flex; align-items:center; justify-content:center; }\n.cd-thumb img{ width:100%; height:100%; object-fit:contain; padding:8%; }\n.cd-title{ font-family:var(--display); font-size:14px; line-height:1.2; }\n.cd-meta{ font-family:var(--mono); font-size:10.5px; letter-spacing:.06em; color:var(--bone-50); margin-top:4px; }\n.cd-plan{ font-family:var(--mono); font-size:9.5px; letter-spacing:.12em; text-transform:uppercase; color:var(--green); margin-top:5px; }\n.cd-qty{ display:flex; align-items:center; gap:8px; margin-top:10px; }\n.cd-qty button{ width:30px;height:30px; border:1px solid var(--ink-line); border-radius:4px; color:var(--bone); font-size:16px; }\n.cd-qty button:hover{ border-color:var(--bone-50); }\n.cd-qty span{ font-family:var(--mono); font-size:13px; min-width:20px; text-align:center; }\n.cd-rm{ margin-left:6px; font-family:var(--mono); font-size:10px; letter-spacing:.1em; text-transform:uppercase; color:var(--bone-32); } .cd-rm:hover{ color:var(--red); }\n.cd-price{ font-family:var(--mono); font-size:13px; }\n.cd-foot{ border-top:1px solid var(--ink-line); padding:20px 22px calc(20px + env(safe-area-inset-bottom)); }\n.cd-sub{ display:flex; justify-content:space-between; align-items:baseline; font-family:var(--display); font-size:18px; }\n.cd-ship{ font-family:var(--mono); font-size:10.5px; letter-spacing:.06em; color:var(--bone-32); margin:8px 0 16px; }\n.cd-checkout{ display:block; text-align:center; background:var(--red); color:var(--bone); font-family:var(--display); font-size:15px; letter-spacing:.02em; border-radius:5px; padding:18px; transition:background .2s; }\n.cd-checkout:hover{ background:#a71f14; }\n.cd-checkout[aria-disabled=\"true\"]{ opacity:.4; pointer-events:none; }\n.cd-toast{ position:fixed; bottom:24px; left:50%; transform:translate(-50%,20px); z-index:90; background:var(--bone); color:var(--ink); font-family:var(--mono); font-size:12px; letter-spacing:.06em; padding:12px 20px; border-radius:6px; opacity:0; pointer-events:none; transition:opacity .25s, transform .25s; }\n.cd-toast.show{ opacity:1; transform:translate(-50%,0); }\n\n/* footer */\n.sp-foot{ padding:clamp(28px,4vw,44px) var(--gutter); border-top:1px solid var(--ink-line-2); font-family:var(--mono); font-size:10.5px; letter-spacing:.08em; color:var(--bone-32); display:flex; flex-wrap:wrap; gap:12px 26px; }\n\n@media (max-width:640px){ .sp-nav .sp-preview-tag{ display:none; } }\n@media (prefers-reduced-motion:reduce){ *{ animation:none !important; } .card:hover{ transform:none; } }\n\n</style>\n</head>\n<body>\n\n<nav class=\"sp-nav\">\n  <a class=\"sp-mark\" href=\"/\" aria-label=\"AFORCE home\">\n    <span class=\"sp-nn\"><span class=\"n1\">N</span><span class=\"bar\"></span><span class=\"n2\">N</span></span> AFORCE\n    <span class=\"sp-preview-tag\">Shop Preview</span>\n  </a>\n  <button class=\"cart-btn\" type=\"button\" data-cart-open>Cart <span data-cart-count data-empty=\"true\">0</span></button>\n</nav>\n\n<main id=\"pdp\" class=\"pdp\" aria-live=\"polite\">\n  <div class=\"pdp-media skel\"></div>\n  <div>\n    <span class=\"pdp-type skel\" style=\"display:inline-block;width:120px;height:12px;\"></span>\n    <h1 class=\"pdp-title skel\" style=\"height:52px;border-radius:4px;margin-top:14px;\"></h1>\n  </div>\n</main>\n<div id=\"state\" class=\"sp-state\" hidden></div>\n\n<footer class=\"sp-foot\">\n  <span>AFORCE Hydration, Inc.</span>\n  <span>Performance Is Non-Negotiable.</span>\n  <span>Preview build — not indexed.</span>\n</footer>\n\n<script>\n/* =====================================================================\n   AForce Headless — CartProvider (vanilla, brand-native slide-out drawer).\n   Mounts ONLY on /shop-preview pages (not global) until cutover.\n   - cart id persisted in first-party cookie `aforce_cart_id` (30-day).\n   - all Shopify calls go through /api/cart/* so the token stays server-side.\n   - optimistic quantity/remove with rollback + toast on error.\n   - checkout CTA → cart.checkoutUrl (Shopify checkout on shop.drinkaforce.com).\n   Exposes window.AForceCart: { addLine, updateLine, removeLine, open, close, refresh, get }.\n   ===================================================================== */\n(function () {\n  \"use strict\";\n\n  var COOKIE = \"aforce_cart_id\";\n  var COOKIE_DAYS = 30;\n  var cart = null;         // last known server cart\n  var loading = false;\n  var els = {};\n\n  /* ---------- cookie ---------- */\n  function setCookie(v) {\n    var d = new Date(); d.setTime(d.getTime() + COOKIE_DAYS * 864e5);\n    document.cookie = COOKIE + \"=\" + encodeURIComponent(v) + \";expires=\" + d.toUTCString() + \";path=/;SameSite=Lax\";\n  }\n  function getCookie() {\n    var m = document.cookie.match(new RegExp(\"(?:^|; )\" + COOKIE + \"=([^;]*)\"));\n    return m ? decodeURIComponent(m[1]) : null;\n  }\n  function clearCookie() { document.cookie = COOKIE + \"=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/\"; }\n\n  /* ---------- api ---------- */\n  function api(path, opts) {\n    return fetch(path, Object.assign({ headers: { \"Content-Type\": \"application/json\" } }, opts))\n      .then(function (r) { return r.json().then(function (j) { if (!r.ok) throw new Error(j.error || (\"HTTP \" + r.status)); return j; }); });\n  }\n\n  /* ---------- money ---------- */\n  function money(m) {\n    if (!m) return \"\";\n    var n = parseFloat(m.amount || 0);\n    try { return new Intl.NumberFormat(\"en-US\", { style: \"currency\", currency: m.currencyCode || \"USD\" }).format(n); }\n    catch (e) { return \"$\" + n.toFixed(2); }\n  }\n\n  /* ---------- render ---------- */\n  function count() { return cart && cart.totalQuantity ? cart.totalQuantity : 0; }\n  function renderBadges() {\n    document.querySelectorAll(\"[data-cart-count]\").forEach(function (b) {\n      var c = count(); b.textContent = c; b.setAttribute(\"data-empty\", c ? \"false\" : \"true\");\n    });\n  }\n  function esc(s) { return (s == null ? \"\" : String(s)).replace(/[&<>\"]/g, function (c) { return ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" })[c]; }); }\n\n  function renderDrawer() {\n    renderBadges();\n    var body = els.body, foot = els.foot;\n    if (!cart || !cart.lines || !cart.lines.nodes.length) {\n      body.innerHTML = '<p class=\"cd-empty\">Your cart is empty.</p>';\n      foot.style.display = \"none\";\n      return;\n    }\n    foot.style.display = \"\";\n    body.innerHTML = cart.lines.nodes.map(function (ln) {\n      var v = ln.merchandise || {};\n      var plan = ln.sellingPlanAllocation && ln.sellingPlanAllocation.sellingPlan;\n      var img = v.image ? '<img src=\"' + esc(v.image.url) + '\" alt=\"' + esc(v.image.altText || \"\") + '\">' : '<span class=\"cd-noimg\"></span>';\n      var opts = (v.selectedOptions || []).filter(function (o) { return o.value && o.value !== \"Default Title\"; })\n        .map(function (o) { return esc(o.value); }).join(\" · \");\n      return '<div class=\"cd-line\" data-line=\"' + esc(ln.id) + '\">' +\n        '<div class=\"cd-thumb\">' + img + '</div>' +\n        '<div class=\"cd-info\">' +\n        '<div class=\"cd-title\">' + esc(v.product ? v.product.title : v.title) + '</div>' +\n        (opts ? '<div class=\"cd-meta\">' + opts + '</div>' : \"\") +\n        (plan ? '<div class=\"cd-plan\">' + esc(plan.name) + '</div>' : '<div class=\"cd-plan\">One-time</div>') +\n        '<div class=\"cd-qty\">' +\n        '<button type=\"button\" data-qd aria-label=\"Decrease\">–</button>' +\n        '<span>' + ln.quantity + '</span>' +\n        '<button type=\"button\" data-qi aria-label=\"Increase\">+</button>' +\n        '<button type=\"button\" class=\"cd-rm\" data-rm>Remove</button>' +\n        '</div>' +\n        '</div>' +\n        '<div class=\"cd-price\">' + money(ln.cost && ln.cost.totalAmount) + '</div>' +\n        '</div>';\n    }).join(\"\");\n    els.subtotal.textContent = money(cart.cost && cart.cost.subtotalAmount);\n    els.checkout.href = cart.checkoutUrl || \"#\";\n    els.checkout.setAttribute(\"aria-disabled\", cart.checkoutUrl ? \"false\" : \"true\");\n  }\n\n  /* ---------- toast ---------- */\n  function toast(msg) {\n    els.toast.textContent = msg; els.toast.classList.add(\"show\");\n    clearTimeout(toast._t); toast._t = setTimeout(function () { els.toast.classList.remove(\"show\"); }, 3200);\n  }\n\n  /* ---------- mutations (optimistic where safe) ---------- */\n  function setLoading(v) { loading = v; els.drawer.setAttribute(\"data-loading\", v ? \"true\" : \"false\"); }\n\n  function addLine(merchandiseId, quantity, opts) {\n    quantity = quantity || 1; opts = opts || {};\n    var line = { merchandiseId: merchandiseId, quantity: quantity };\n    if (opts.sellingPlanId) line.sellingPlanId = opts.sellingPlanId;\n    setLoading(true);\n    var id = getCookie();\n    var p = id\n      ? api(\"/api/cart/add\", { method: \"POST\", body: JSON.stringify({ cartId: id, lines: [line] }) })\n      : api(\"/api/cart/create\", { method: \"POST\", body: JSON.stringify({ lines: [line] }) });\n    return p.then(function (j) {\n      if (!id && j.cart) setCookie(j.cart.id);\n      cart = j.cart; renderDrawer(); open(); toast(\"Added to cart\");\n    }).catch(function (e) {\n      // A stale/expired cart id can make add fail — recreate once.\n      if (id) { clearCookie(); return api(\"/api/cart/create\", { method: \"POST\", body: JSON.stringify({ lines: [line] }) })\n        .then(function (j) { if (j.cart) setCookie(j.cart.id); cart = j.cart; renderDrawer(); open(); toast(\"Added to cart\"); })\n        .catch(function (e2) { toast(\"Couldn't add — try again\"); }); }\n      toast(\"Couldn't add — try again\");\n    }).finally(function () { setLoading(false); });\n  }\n\n  function updateLine(lineId, quantity) {\n    var id = getCookie(); if (!id) return Promise.resolve();\n    if (quantity <= 0) return removeLine(lineId);\n    // optimistic\n    var prev = JSON.parse(JSON.stringify(cart));\n    var ln = cart.lines.nodes.filter(function (l) { return l.id === lineId; })[0];\n    if (ln) { ln.quantity = quantity; renderDrawer(); }\n    setLoading(true);\n    return api(\"/api/cart/update\", { method: \"POST\", body: JSON.stringify({ cartId: id, lines: [{ id: lineId, quantity: quantity }] }) })\n      .then(function (j) { cart = j.cart; renderDrawer(); })\n      .catch(function () { cart = prev; renderDrawer(); toast(\"Couldn't update — reverted\"); })\n      .finally(function () { setLoading(false); });\n  }\n\n  function removeLine(lineId) {\n    var id = getCookie(); if (!id) return Promise.resolve();\n    var prev = JSON.parse(JSON.stringify(cart));\n    cart.lines.nodes = cart.lines.nodes.filter(function (l) { return l.id !== lineId; }); renderDrawer();\n    setLoading(true);\n    return api(\"/api/cart/remove\", { method: \"POST\", body: JSON.stringify({ cartId: id, lineIds: [lineId] }) })\n      .then(function (j) { cart = j.cart; renderDrawer(); })\n      .catch(function () { cart = prev; renderDrawer(); toast(\"Couldn't remove — reverted\"); })\n      .finally(function () { setLoading(false); });\n  }\n\n  function refresh() {\n    var id = getCookie(); if (!id) { renderDrawer(); return Promise.resolve(); }\n    return api(\"/api/cart/get?id=\" + encodeURIComponent(id)).then(function (j) {\n      if (!j.cart) { clearCookie(); cart = null; } else { cart = j.cart; }\n      renderDrawer();\n    }).catch(function () { /* keep last state */ });\n  }\n\n  /* ---------- drawer open/close ---------- */\n  function open() { els.drawer.classList.add(\"open\"); els.veil.classList.add(\"open\"); document.body.style.overflow = \"hidden\"; }\n  function close() { els.drawer.classList.remove(\"open\"); els.veil.classList.remove(\"open\"); document.body.style.overflow = \"\"; }\n\n  /* ---------- mount ---------- */\n  function mount() {\n    var wrap = document.createElement(\"div\");\n    wrap.innerHTML =\n      '<div class=\"cd-veil\" data-cart-veil></div>' +\n      '<aside class=\"cd-drawer\" data-cart-drawer aria-label=\"Cart\" data-loading=\"false\">' +\n      '<header class=\"cd-head\"><span>Your Ritual</span><button type=\"button\" class=\"cd-close\" data-cart-close aria-label=\"Close cart\">×</button></header>' +\n      '<div class=\"cd-lines\" data-cart-body></div>' +\n      '<footer class=\"cd-foot\" data-cart-foot>' +\n      '<div class=\"cd-sub\"><span>Subtotal</span><span data-cart-subtotal></span></div>' +\n      '<p class=\"cd-ship\">Shipping &amp; taxes calculated at checkout.</p>' +\n      '<a class=\"cd-checkout\" data-cart-checkout href=\"#\">Checkout →</a>' +\n      '</footer></aside>' +\n      '<div class=\"cd-toast\" data-cart-toast role=\"status\"></div>';\n    document.body.appendChild(wrap);\n    els.veil = wrap.querySelector(\"[data-cart-veil]\");\n    els.drawer = wrap.querySelector(\"[data-cart-drawer]\");\n    els.body = wrap.querySelector(\"[data-cart-body]\");\n    els.foot = wrap.querySelector(\"[data-cart-foot]\");\n    els.subtotal = wrap.querySelector(\"[data-cart-subtotal]\");\n    els.checkout = wrap.querySelector(\"[data-cart-checkout]\");\n    els.toast = wrap.querySelector(\"[data-cart-toast]\");\n\n    els.veil.addEventListener(\"click\", close);\n    wrap.querySelector(\"[data-cart-close]\").addEventListener(\"click\", close);\n    document.addEventListener(\"keydown\", function (e) { if (e.key === \"Escape\") close(); });\n\n    document.addEventListener(\"click\", function (e) {\n      if (e.target.closest(\"[data-cart-open]\")) { e.preventDefault(); open(); }\n      var line = e.target.closest(\".cd-line\"); if (!line) return;\n      var id = line.getAttribute(\"data-line\");\n      var ln = cart && cart.lines.nodes.filter(function (l) { return l.id === id; })[0];\n      if (!ln) return;\n      if (e.target.closest(\"[data-qi]\")) updateLine(id, ln.quantity + 1);\n      else if (e.target.closest(\"[data-qd]\")) updateLine(id, ln.quantity - 1);\n      else if (e.target.closest(\"[data-rm]\")) removeLine(id);\n    });\n\n    renderDrawer();\n    refresh();\n  }\n\n  window.AForceCart = { addLine: addLine, updateLine: updateLine, removeLine: removeLine, open: open, close: close, refresh: refresh, get: function () { return cart; } };\n  if (document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\", mount); else mount();\n})();\n\n</script>\n<script>\n(function(){\n  \"use strict\";\n  function money(m){ if(!m) return \"\"; var n=parseFloat(m.amount||0); try{return new Intl.NumberFormat(\"en-US\",{style:\"currency\",currency:m.currencyCode||\"USD\"}).format(n);}catch(e){return \"$\"+n.toFixed(2);} }\n  function esc(s){ return (s==null?\"\":String(s)).replace(/[&<>\"]/g,function(c){return({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"})[c];}); }\n  function handleFromPath(){\n    var parts=location.pathname.replace(/\\/+$/,\"\").split(\"/\");\n    var last=parts[parts.length-1];\n    return (last && last!==\"shop-preview\" && last!==\"product.html\") ? decodeURIComponent(last) : (new URLSearchParams(location.search).get(\"handle\")||\"\");\n  }\n  var selected=null, product=null;\n\n  function render(p){\n    product=p;\n    var vs=(p.variants&&p.variants.nodes)||[];\n    selected=vs.filter(function(v){return v.availableForSale;})[0]||vs[0]||null;\n    var img=p.featuredImage?('<img src=\"'+esc(p.featuredImage.url)+'\" alt=\"'+esc(p.featuredImage.altText||p.title)+'\">'):'';\n    var multi=vs.length>1;\n    var variantHtml=multi?('<div class=\"pdp-variants\" id=\"variants\">'+vs.map(function(v){\n      return '<button class=\"variant'+(v===selected?' on':'')+(v.availableForSale?'':' oos')+'\" type=\"button\" data-v=\"'+esc(v.id)+'\">'+esc(v.title)+'</button>';\n    }).join(\"\")+'</div>'):'';\n    document.getElementById(\"pdp\").innerHTML=\n      '<div class=\"pdp-media\">'+img+'</div>'+\n      '<div>'+\n        '<a class=\"pdp-back\" href=\"/shop-preview\">← All products</a>'+\n        (p.productType?'<div class=\"pdp-type\">'+esc(p.productType)+'</div>':'')+\n        '<h1 class=\"pdp-title\">'+esc(p.title)+'</h1>'+\n        '<div class=\"pdp-price\" id=\"price\">'+money(selected&&selected.price)+'</div>'+\n        (p.description?'<p class=\"pdp-desc\">'+esc(p.description)+'</p>':'')+\n        variantHtml+\n        '<button class=\"btn btn-primary pdp-add\" id=\"add\" type=\"button\">Add to cart</button>'+\n        '<p class=\"pdp-note\">Shipping &amp; taxes calculated at checkout · secure checkout on shop.drinkaforce.com</p>'+\n      '</div>';\n    syncAdd();\n  }\n  function syncAdd(){\n    var add=document.getElementById(\"add\");\n    var ok=selected&&selected.availableForSale;\n    add.disabled=!ok; add.textContent=ok?\"Add to cart\":\"Sold out\";\n    var pr=document.getElementById(\"price\"); if(pr&&selected) pr.textContent=money(selected.price);\n  }\n  function showState(html){ document.getElementById(\"pdp\").style.display=\"none\"; var s=document.getElementById(\"state\"); s.innerHTML=html; s.hidden=false; }\n\n  document.addEventListener(\"click\",function(e){\n    var vb=e.target.closest(\"[data-v]\");\n    if(vb){ var id=vb.getAttribute(\"data-v\"); selected=(product.variants.nodes||[]).filter(function(v){return v.id===id;})[0];\n      document.querySelectorAll(\"#variants .variant\").forEach(function(b){ b.classList.toggle(\"on\", b===vb); }); syncAdd(); return; }\n    if(e.target.closest(\"#add\")){ var add=e.target.closest(\"#add\"); if(!selected) return;\n      add.disabled=true; add.textContent=\"Adding…\";\n      window.AForceCart.addLine(selected.id,1).finally(function(){ add.disabled=false; syncAdd(); }); }\n  });\n\n  var handle=handleFromPath();\n  if(!handle){ showState('<p class=\"mono\">Product not specified.</p>'); return; }\n  fetch(\"/api/shop/product?handle=\"+encodeURIComponent(handle))\n    .then(function(r){ return r.json().then(function(j){ if(!r.ok) throw Object.assign(new Error(j.error||(\"HTTP \"+r.status)),{status:r.status}); return j; }); })\n    .then(function(j){ if(!j.product){ showState('<p class=\"mono\">Product not found.</p>'); return; } render(j.product); })\n    .catch(function(e){\n      if(e.status===404){ showState('<p class=\"mono\">Not found.</p>'); }\n      else if(e.status===503){ showState('<p class=\"mono\">Connect Shopify to load this product.</p>'); }\n      else{ showState('<p class=\"mono\">Couldn’t load this product.</p>'); }\n    });\n})();\n</script>\n</body>\n</html>\n"
};
